const b = $json.body || {};
const issueId = String(b.issue_id || b.data?.id || '').trim();
if (!issueId) return [{json:{ok:false,status:'rejected',reason:'missing issue_id'}}];
return [{json:{ok:true,issue_id:issueId,relay_request_id:String(b.request_id || $execution.id)}}];

const r = $json;
if (r.error) return [{json:{ok:false,status:'rejected',reason:'linear_api_error',detail:String(r.error.message||r.error)}}];
const issue = r.data?.issue;
if (!issue?.id) return [{json:{ok:false,status:'rejected',reason:'linear_issue_not_found'}}];
const split = v => String(v||'').split(',').map(x=>x.trim()).filter(Boolean);
const allowedTeams = new Set(split($env.LINEAR_ALLOWED_TEAM_KEYS));
const allowedProjects = new Set(split($env.LINEAR_ALLOWED_PROJECT_IDS));
let repoMap={}; try { repoMap=JSON.parse($env.LINEAR_REPOSITORY_MAP_JSON||'{}'); } catch {}
if (!allowedTeams.size) return [{json:{ok:false,status:'rejected',reason:'LINEAR_ALLOWED_TEAM_KEYS_not_configured'}}];
if (!allowedTeams.has(issue.team?.key)) return [{json:{ok:false,status:'rejected',reason:'team_not_allowlisted',team:issue.team?.key}}];
if (allowedProjects.size && !allowedProjects.has(issue.project?.id || '')) return [{json:{ok:false,status:'rejected',reason:'project_not_allowlisted',project:issue.project?.id||null}}];
const repository = repoMap[issue.team?.key] || '';
if (!repository) return [{json:{ok:false,status:'rejected',reason:'repository_mapping_missing'}}];
const labels=(issue.labels?.nodes||[]).map(x=>String(x.name||''));
const labelSet=new Set(labels.map(x=>x.toLowerCase()));
if (!labelSet.has('agent:auto')) return [{json:{ok:false,status:'rejected',reason:'agent_auto_label_required',issue_id:issue.id}}];
const text=[issue.title||'',issue.description||'',...labels].join(' ').toLowerCase();
const blocked=['production secret','deployment credential','rotate secret','delete production data'];
const sensitive=['auth','authentication','authorization','billing','permission','permissions','secret','secrets','production data','credential','credentials'];
const blockedHit=blocked.filter(x=>text.includes(x));
if (blockedHit.length) return [{json:{ok:false,status:'blocked',reason:'blocked_sensitive_domain',matches:blockedHit,issue_id:issue.id}}];
const sensitiveHit=sensitive.filter(x=>text.includes(x));
const sensitivity=sensitiveHit.length?'review_required':'normal';
const allowedPaths=['docs/**','workflows/core/**','workflows/autonomous/**','workflows/observability/**','benchmarks/**','tests/**'];
const forbiddenPaths=['.agent/**','.github/**','workflows/actions/**','scripts/validate_workflows.py','scripts/test_contracts.py','agentic_engineering/**'];
const task={task_id:`linear-${issue.identifier||issue.id}`,source:{provider:'linear',source_id:issue.id,provenance:'linear_api',url:issue.url||null},repository,base_ref:'main',title:issue.title||issue.identifier,description:issue.description||'',labels,priority:issue.priority??null,allowed_paths:allowedPaths,forbidden_paths:forbiddenPaths,verification_profile:'platform',sensitivity,authorization:{auto_label_verified:true,human_review_granted:false}};
return [{json:{ok:true,status:sensitivity==='normal'?'eligible':'escalate',task,sensitive_matches:sensitiveHit}}];
